contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function
    // params:
    //  - caller: address that will call sendTo (simulated via this contract's call origin not changeable, so we pass in receiver and amount)
    // We cannot change msg.sender when calling c from this contract, so to observe owner-only behavior
    // we rely on the fact that in the original contract only the deployer (owner) can make c send funds.
    // The test: if the contract c has a positive balance and some receiver != address(0) and amount>0,
    // then calling sendTo from THIS contract should revert (i.e., fail) unless THIS contract is the owner.
    // We express this by requiring that a send attempt either reverts or leaves c's balance unchanged;
    // on the original (owner-only) version, since this contract is not the owner in general, the call will revert
    // and c's balance remains the same. On the mutant (allow-all), the call succeeds and reduces c's balance.

    function test_send_restriction(address payable receiver, uint256 amount) public {
        // preconditions for meaningful call
        require(receiver != address(0));
        require(amount > 0);

        // Snapshot balance of c before the call
        uint256 before = address(c).balance;

        // Attempt the state-changing call. This must be a top-level statement.
        // We perform a low-level call to capture success/failure without reverting the whole test.
        // Build calldata for sendTo(address,uint256)
        bytes memory data = abi.encodeWithSignature("sendTo(address,uint256)", receiver, amount);
        (bool success, ) = address(c).call(data);

        // Snapshot after
        uint256 after = address(c).balance;

        // The distinguishing assertion: either the call failed (success==false) OR the balance did not decrease.
        // On the original contract (owner-only), an external caller that is not owner will cause sendTo to revert,
        // so success==false and the assertion holds. On the mutant (allow-all), the call succeeds and the balance
        // decreases when amount<=before, violating the assertion for typical inputs.
        assert(success == false || after >= before);
    }

    // allow contract to receive ETH so it can supply c if needed
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    // caller must not be the owner to witness the difference; ensure msg.sender is not owner by requiring reverted behavior
    function run(address receiver, uint amount) public payable {
        require(receiver != address(0));
        bool reverted;
        try c.sendTo(receiver, amount) { reverted = false; } catch { reverted = true; }
        // On the original contract P, non-owner callers always get a revert from sendTo; in the mutant M they may succeed.
        assert(reverted);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    // caller must not be the owner to witness the difference; ensure msg.sender is not owner by requiring reverted behavior
    function run(address receiver, uint amount) public payable {
        require(receiver != address(0));
        // Ensure the caller is not the deployed contract's owner by requiring msg.sender != c.owner()
        // Because C.owner is not exposed as a function, we instead require that msg.sender != address(c).owner
        // Access the stored owner by reading through a low-level staticcall to the storage slot where owner is stored.
        // Owner is the first state variable; its storage slot 0 contains the address. We ensure msg.sender differs from that stored address.
        {
            // Read slot 0 of contract c to obtain owner address
            (bool ok, bytes memory data) = address(c).staticcall(abi.encodeWithSignature("owner()"));
            if (ok && data.length >= 32) {
                address ownerAddr = address(uint160(uint256(bytes32(data))));
                require(msg.sender != ownerAddr);
            } else {
                // Fallback: if owner() not present, read raw storage slot 0
                bytes32 slot0;
                assembly {
                    // allocate memory for return data
                    let ptr := mload(0x40)
                    // extcodecopy not appropriate; use extcodecopy for code; use extcodesize to ensure contract exists
                    // use extcodecopy not needed; instead use extcodehash to ensure contract present
                    // perform staticcall to get storage via DELEGATECALL is not possible; use extcodehash as a crude check
                    // directly perform extcodecopy of first 32 bytes of code won't give storage; so use sload via DELEGATECALL impossible
                    // instead, try STATICCALL of a nonexistent function to get revert; as fallback, require a conservative condition
                    // if we cannot read owner, require that msg.sender != address(c) to avoid owner-like aliasing
                }
                require(msg.sender != address(c));
            }
        }
        bool reverted;
        try c.sendTo(receiver, amount) { reverted = false; } catch { reverted = true; }
        // On the original contract P, non-owner callers always get a revert from sendTo; in the mutant M they may succeed.
        assert(reverted);
    }
    receive() external payable {}
