    function setUp() public { c = new C(); }

    // Fuzz the receiver and the amount. The general rule: calling sendTo with any receiver
    // and amount should NOT decrease address(c).balance when the call is made by the owner
    // without providing contract funds (i.e., because transfer moves Ether out only if the
    // contract holds balance). In the reference, the zero-address is forbidden, so attempts
    // to send to address(0) cannot change observable balance; the mutant allowing zero-address
    // can attempt an actual transfer to address(0) which affects address(c).balance for some inputs.
    function testFuzz_property(address receiver, uint256 amount) public {
        // Keep domain wide but reasonable: amount must be > 0 per function requirement
        // and receiver is any address (including zero) as fuzzed.
        vm.assume(amount > 0);

        // Fund the contract so that a transfer out would change address(c).balance if allowed.
        // Use a large funding amount to cover fuzzed `amount` values.
        address funder = address(0xBEEF);
        vm.deal(funder, 1 ether);
        vm.prank(funder);
        // send 1 ether to contract
        (bool suc, ) = address(c).call{value: 1 ether}("");
        require(suc, "funding failed");

        // Ensure the caller is the owner (the account that deployed c in setUp()).
        // c was deployed in setUp() from this test contract, so the owner is this contract.
        // Call sendTo as this contract.
        uint256 before = address(c).balance;

        bool ok;
        try c.sendTo(receiver, amount) {
            ok = true;
        } catch {
            ok = false;
