import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // Fuzz the receiver and the amount. The distinguishing behavior is whether sending to address(0)
    // is allowed: reference rejects it so no Ether leaves the contract (address(c).balance unchanged);
    // mutant may attempt to transfer to address(0) and change address(c).balance.
    function testFuzz_property(address receiver, uint256 amount) public {
        // keep amount within a reasonable ETH range and positive (requirement in contract)
        amount = bound(amount, 0, 1 ether);
        vm.assume(amount > 0);

        // fund the contract so it can attempt transfers
        vm.deal(address(this), 2 ether);
        // deposit the amount into c by calling a payable helper path: use self-destruct trick via helper
        Depositor d = new Depositor();
        // fund depositor then selfdestruct to c to seed its balance
        vm.deal(address(d), amount);
        d.destroyAndSend(payable(address(c)));

        // record balance before calling sendTo
        uint256 before = address(c).balance;

        // act as the owner (deployer) since setUp created c by this contract
        // this contract is msg.sender in constructor, so we are owner
        bool ok;
        try c.sendTo(receiver, amount) {
            ok = true;
        } catch {
            ok = false;
        }

        // After the call completes, for the reference implementation the guard require(receiver != address(0))
        // ensures that any call attempting to send to address(0) reverts and so address(c).balance == before.
        // Therefore the universal property we assert is that either the call reverted (ok==false) and balance unchanged,
        // or the call succeeded and balance decreased by exactly amount (a successful transfer to a non-zero address).
        // This single assertTrue observes c via address(c).balance to distinguish the mutant which may allow a
        // silent transfer attempt to address(0) that changes balance in ways the reference would not.

        uint256 after = address(c).balance;

        // The invariant: if the call succeeded, c.balance should have decreased by amount; if it reverted, balance unchanged.
        assertTrue((ok && after + amount == before) || (!ok && after == before));
    }
}

// Minimal helper to deposit Ether into C by self-destructing and sending its balance
contract Depositor {
    function destroyAndSend(address payable to) external {
        selfdestruct(to);
    }
}

